#include "stm32g4xx.h"

void I2C3_Init(void) {
    // 1. Enable GPIOC and I2C3 clocks
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOCEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C3EN;

    // 2. Configure PC8 (SCL) and PC9 (SDA) as AF8, Open-Drain, High Speed, Pull-up
    GPIOC->MODER &= ~((3U << (8 * 2)) | (3U << (9 * 2)));
    GPIOC->MODER |=  ((2U << (8 * 2)) | (2U << (9 * 2))); // AF mode

    GPIOC->OTYPER |= ((1U << 8) | (1U << 9));             // Open-drain

    GPIOC->OSPEEDR |= ((3U << (8 * 2)) | (3U << (9 * 2)));// High speed

    GPIOC->PUPDR &= ~((3U << (8 * 2)) | (3U << (9 * 2)));
    GPIOC->PUPDR |=  ((1U << (8 * 2)) | (1U << (9 * 2))); // Pull-up

    // PC8 -> AF8 (AFRH index 0), PC9 -> AF8 (AFRH index 1)
    GPIOC->AFR[1] &= ~((0xFU << ((8 - 8) * 4)) | (0xFU << ((9 - 8) * 4)));
    GPIOC->AFR[1] |=  ((8U << ((8 - 8) * 4)) | (8U << ((9 - 8) * 4)));

    // 3. Configure I2C3 timing for 100 kHz standard mode with f_I2CCLK = 16 MHz (HSI16 / PCLK default)
    // PRESC=3, SCLL=0x13, SCLH=0x0F, SDADEL=0x2, SCLDEL=0x4 (Table 360, RM0440 p. 1657)
    I2C3->CR1 &= ~I2C_CR1_PE;
    I2C3->TIMINGR = (3U << 28) | (4U << 20) | (2U << 16) | (0x0FU << 8) | (0x13U << 0);

    // 4. Enable I2C3
    I2C3->CR1 |= I2C_CR1_PE;
}

#include "stm32g4xx.h"

/**
 * @brief Initialize I2C3 on PC8 (SCL) and PC9 (SDA) for BME280 communication.
 *        Configured for 100 kHz Standard Mode with f_I2CCLK = 16 MHz.
 */
void I2C3_Init(void) {
    // 1. Enable GPIOC and I2C3 peripheral clocks
    RCC->AHB2ENR  |= RCC_AHB2ENR_GPIOCEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C3EN;

    // 2. Configure PC8 (SCL) and PC9 (SDA)
    // MODER: Alternate Function mode ('10') on pins 8 and 9
    GPIOC->MODER &= ~((3U << (8 * 2)) | (3U << (9 * 2)));
    GPIOC->MODER |=  ((2U << (8 * 2)) | (2U << (9 * 2)));

    // OTYPER: Open-drain ('1') on pins 8 and 9
    GPIOC->OTYPER |= ((1U << 8) | (1U << 9));

    // OSPEEDR: Very high speed ('11')
    GPIOC->OSPEEDR |= ((3U << (8 * 2)) | (3U << (9 * 2)));

    // PUPDR: Internal pull-ups enabled (note: external pull-ups to 3.3V on the shifter board are recommended)
    GPIOC->PUPDR &= ~((3U << (8 * 2)) | (3U << (9 * 2)));
    GPIOC->PUPDR |=  ((1U << (8 * 2)) | (1U << (9 * 2)));

    // AFR[1] (AFRH): Route AF8 (I2C3) to PC8 (pin 8 -> AFR[1] bits [3:0]) and PC9 (pin 9 -> AFR[1] bits [7:4])
    GPIOC->AFR[1] &= ~((0xFU << ((8 - 8) * 4)) | (0xFU << ((9 - 8) * 4)));
    GPIOC->AFR[1] |=  ((8U   << ((8 - 8) * 4)) | (8U   << ((9 - 8) * 4)));

    // 3. Configure I2C3 timing: 100 kHz standard mode with 16 MHz kernel clock
    // RM0440 p. 1657 Table 360: PRESC=3, SCLDEL=4, SDADEL=2, SCLH=0x0F, SCLL=0x13
    I2C3->CR1 &= ~I2C_CR1_PE; // Peripheral disable before setting TIMINGR
    I2C3->TIMINGR = (3U << 28) | (4U << 20) | (2U << 16) | (0x0FU << 8) | (0x13U << 0);

    // 4. Enable I2C3 peripheral
    I2C3->CR1 |= I2C_CR1_PE;
}

